    stageState = {};
    runStartMs = null;
    renderPanels(r);
    renderStrip();
    document.getElementById("timeline").innerHTML = "";
    Array.prototype.forEach.call(document.querySelectorAll("#runs li"), function (li) {
      li.className = li.textContent.indexOf(r.runId + " (") === 0 ? "selected" : "";
    });
    if (es) es.close();
